// ============================================================================
// Root Store
// ============================================================================

export class RootStore {
  user: UserStore
  menuCategory: MenuCategoryStore
  menuItem: MenuItemStore
  table: TableStore
  order: OrderStore
  orderItem: OrderItemStore
  inventoryItem: InventoryItemStore
  inventoryTransaction: InventoryTransactionStore
  dailyReport: DailyReportStore

  constructor() {
    this.user = new UserStore()
    this.menuCategory = new MenuCategoryStore()
    this.menuItem = new MenuItemStore()
    this.table = new TableStore()
    this.order = new OrderStore()
    this.orderItem = new OrderItemStore()
    this.inventoryItem = new InventoryItemStore()
    this.inventoryTransaction = new InventoryTransactionStore()
    this.dailyReport = new DailyReportStore()
    makeAutoObservable(this)
  }

  /** Clear all stores */
  clearAll() {
    this.user.clear()
    this.menuCategory.clear()
    this.menuItem.clear()
    this.table.clear()
    this.order.clear()
    this.orderItem.clear()
    this.inventoryItem.clear()
    this.inventoryTransaction.clear()
    this.dailyReport.clear()
  }
}

// ============================================================================
// Factory & Singleton
// ============================================================================

let rootStore: RootStore | null = null

/**
 * Get or create the root store singleton
 */
export function getStore(): RootStore {
  if (!rootStore) {
    rootStore = new RootStore()
  }
  return rootStore
}

/**
 * Create a new root store (for testing or SSR)
 */
export function createStore(): RootStore {
  return new RootStore()
}

/**
 * Reset the singleton store
 */
export function resetStore(): void {
  rootStore = null
}
